/* cppi::b5b2d219e7f8f54413d0d15a10715fd8d289c9c4b8d30828ebd7393c3dce572c */
SELECT COUNT(*) FROM (SELECT cmb.business_date, cmb.pbor_node_name, cmb.pools_mv, cmb.pools_pnl + coalesce(opx.opex, 0) AS pools_pnl, round(sl.seclvl_mv, 2) AS seclvl_mv, round(sl.seclvl_pnl, 2) AS seclvl_pnl, round(cmb.pools_mv - sl.seclvl_mv, 2) AS mv_diff, round((cmb.pools_pnl + coalesce(opx.opex, 0)) - sl.seclvl_pnl, 2) AS pnl_diff FROM (SELECT CAST(business_date AS date) AS business_date, pbor_node_name, market_value_reporting_currency AS pools_mv, pnl_reporting_currency AS pools_pnl FROM performance.scd_performance_bottom_up WHERE dataset_id = 'CMBP_NET' AND business_date IN (SELECT DISTINCT business_date FROM performance.scd_performance_bottom_up WHERE business_date <= (SELECT max(business_date) FROM performance.scd_performance_bottom_up) ORDER BY business_date DESC LIMIT 90)) cmb LEFT JOIN (SELECT business_date, model_portfolio, sum(opex) AS opex FROM (SELECT date(date_add('day', -1, date_add('month', 1, date_parse(concat(month, ' ', CAST(CASE WHEN month NOT IN ('Jan', 'Feb', 'Mar') THEN fiscal_year - 1 ELSE fiscal_year END AS varchar)), '%b %Y')))) AS business_date, model_portfolio, sum_of_debit_credit_pc AS opex FROM ioa.fa_totalcost_transaction_details WHERE total_cost_name IN ('CUSTODY', 'G&A', 'PERSONNEL', 'TAXES', 'OTHER INCOME ADJUSTMENT 2')) GROUP BY business_date, model_portfolio) opx ON cmb.business_date = opx.business_date AND cmb.pbor_node_name = opx.model_portfolio RIGHT JOIN (SELECT CAST(business_date AS date) AS business_date, aggregation_level_1, sum(market_value_reporting_currency) AS seclvl_mv, sum(period_result_node_by_node_reporting_currency) AS seclvl_pnl FROM performance.scd_performance_seclvl WHERE business_date IN (SELECT DISTINCT business_date FROM performance.scd_performance_bottom_up WHERE business_date <= (SELECT max(business_date) FROM performance.scd_performance_bottom_up) ORDER BY business_date DESC LIMIT 90) GROUP BY business_date, aggregation_level_1 ORDER BY business_date, aggregation_level_1) sl ON cmb.business_date = sl.business_date AND cmb.pbor_node_name = sl.aggregation_level_1 WHERE abs(cmb.pools_mv - sl.seclvl_mv) > 1 OR abs((cmb.pools_pnl + coalesce(opx.opex, 0)) - sl.seclvl_pnl) > 1
) dbvrcnt

/* cppi::b5b2d219e7f8f54413d0d15a10715fd8d289c9c4b8d30828ebd7393c3dce572c */
SELECT COUNT(*) FROM (SELECT cmb.business_date, cmb.pbor_node_name, cmb.pools_mv, cmb.pools_pnl + coalesce(opx.opex, 0) AS pools_pnl, round(sl.seclvl_mv, 2) AS seclvl_mv, round(sl.seclvl_pnl, 2) AS seclvl_pnl, round(cmb.pools_mv - sl.seclvl_mv, 2) AS mv_diff, round((cmb.pools_pnl + coalesce(opx.opex, 0)) - sl.seclvl_pnl, 2) AS pnl_diff FROM (SELECT CAST(business_date AS date) AS business_date, pbor_node_name, market_value_reporting_currency AS pools_mv, pnl_reporting_currency AS pools_pnl FROM performance.scd_performance_bottom_up WHERE dataset_id = 'CMBP_NET' AND business_date IN (SELECT DISTINCT business_date FROM performance.scd_performance_bottom_up WHERE business_date <= (SELECT max(business_date) FROM performance.scd_performance_bottom_up) ORDER BY business_date DESC LIMIT 90)) cmb LEFT JOIN (SELECT business_date, model_portfolio, sum(opex) AS opex FROM (SELECT date(date_add('day', -1, date_add('month', 1, date_parse(concat(month, ' ', CAST(CASE WHEN month NOT IN ('Jan', 'Feb', 'Mar') THEN fiscal_year - 1 ELSE fiscal_year END AS varchar)), '%b %Y')))) AS business_date, model_portfolio, sum_of_debit_credit_pc AS opex FROM ioa.fa_totalcost_transaction_details WHERE total_cost_name IN ('CUSTODY', 'G&A', 'PERSONNEL', 'TAXES', 'OTHER INCOME ADJUSTMENT 2')) GROUP BY business_date, model_portfolio) opx ON cmb.business_date = opx.business_date AND cmb.pbor_node_name = opx.model_portfolio RIGHT JOIN (SELECT CAST(business_date AS date) AS business_date, aggregation_level_1, sum(market_value_reporting_currency) AS seclvl_mv, sum(period_result_node_by_node_reporting_currency) AS seclvl_pnl FROM performance.scd_performance_seclvl WHERE business_date IN (SELECT DISTINCT business_date FROM performance.scd_performance_bottom_up WHERE business_date <= (SELECT max(business_date) FROM performance.scd_performance_bottom_up) ORDER BY business_date DESC LIMIT 90) GROUP BY business_date, aggregation_level_1 ORDER BY business_date, aggregation_level_1) sl ON cmb.business_date = sl.business_date AND cmb.pbor_node_name = sl.aggregation_level_1 WHERE abs(cmb.pools_mv - sl.seclvl_mv) > 1 OR abs((cmb.pools_pnl + coalesce(opx.opex, 0)) - sl.seclvl_pnl) > 1
) dbvrcnt

/* cppi::b5b2d219e7f8f54413d0d15a10715fd8d289c9c4b8d30828ebd7393c3dce572c */
SELECT COUNT(*) FROM (SELECT cmb.business_date, cmb.pbor_node_name, cmb.pools_mv, cmb.pools_pnl + coalesce(opx.opex, 0) AS pools_pnl, round(sl.seclvl_mv, 2) AS seclvl_mv, round(sl.seclvl_pnl, 2) AS seclvl_pnl, round(cmb.pools_mv - sl.seclvl_mv, 2) AS mv_diff, round((cmb.pools_pnl + coalesce(opx.opex, 0)) - sl.seclvl_pnl, 2) AS pnl_diff FROM (SELECT CAST(business_date AS date) AS business_date, pbor_node_name, market_value_reporting_currency AS pools_mv, pnl_reporting_currency AS pools_pnl FROM performance.scd_performance_bottom_up WHERE dataset_id = 'CMBP_NET' AND business_date IN (SELECT DISTINCT business_date FROM performance.scd_performance_bottom_up WHERE business_date <= (SELECT max(business_date) FROM performance.scd_performance_bottom_up) ORDER BY business_date DESC LIMIT 90)) cmb LEFT JOIN (SELECT business_date, model_portfolio, sum(opex) AS opex FROM (SELECT date(date_add('day', -1, date_add('month', 1, date_parse(concat(month, ' ', CAST(CASE WHEN month NOT IN ('Jan', 'Feb', 'Mar') THEN fiscal_year - 1 ELSE fiscal_year END AS varchar)), '%b %Y')))) AS business_date, model_portfolio, sum_of_debit_credit_pc AS opex FROM ioa.fa_totalcost_transaction_details WHERE total_cost_name IN ('CUSTODY', 'G&A', 'PERSONNEL', 'TAXES', 'OTHER INCOME ADJUSTMENT 2')) GROUP BY business_date, model_portfolio) opx ON cmb.business_date = opx.business_date AND cmb.pbor_node_name = opx.model_portfolio RIGHT JOIN (SELECT CAST(business_date AS date) AS business_date, aggregation_level_1, sum(market_value_reporting_currency) AS seclvl_mv, sum(period_result_node_by_node_reporting_currency) AS seclvl_pnl FROM performance.scd_performance_seclvl WHERE business_date IN (SELECT DISTINCT business_date FROM performance.scd_performance_bottom_up WHERE business_date <= (SELECT max(business_date) FROM performance.scd_performance_bottom_up) ORDER BY business_date DESC LIMIT 90) GROUP BY business_date, aggregation_level_1 ORDER BY business_date, aggregation_level_1) sl ON cmb.business_date = sl.business_date AND cmb.pbor_node_name = sl.aggregation_level_1 WHERE abs(cmb.pools_mv - sl.seclvl_mv) > 1 OR abs((cmb.pools_pnl + coalesce(opx.opex, 0)) - sl.seclvl_pnl) > 1
